def show_maa_image(width=None):
    """Display Maa Durga with the current weekday dress colour and IST light/dark phase."""
    try:
        if os.path.exists(MAA_IMAGE):
            with open(MAA_IMAGE, "rb") as f:
                img64 = base64.b64encode(f.read()).decode("utf-8")
        else:
            img64 = MAA_IMAGE_B64
        dress = TODAY_THEME["primary"]
        if THEME_PHASE == "Dark":
            # Slightly deepen the dress tone at night while keeping the day's colour.
            dress = TODAY_THEME["deep"]
        html = f"""
        <div class=\"maa-stage\">
          <img src=\"data:image/png;base64,{img64}\" class=\"maa-img\" />
          <div class=\"maa-dress-tint\" style=\"background:{dress};\"></div>
          <div class=\"maa-glow\" style=\"box-shadow:0 0 55px 18px {TODAY_THEME['accent']}55;\"></div>
        </div>
        """
        st.markdown(html, unsafe_allow_html=True)
    except Exception:
        st.image(io.BytesIO(base64.b64decode(MAA_IMAGE_B64)), use_container_width=True)


START_BALANCE = 10000000000001.00


