# ============================================================
# DAILY DYNAMIC MANDIR THEME
# India/IST weekday theme:
# Monday white | Tuesday pinkish red | Wednesday green |
# Thursday yellow | Friday silver | Saturday bright blue |
# Sunday maroon/orange
# ============================================================
WEEKDAY_THEMES = {
    0: {"name": "White", "primary": "#f5f5f2", "deep": "#3d3d3a", "accent": "#b8a46a", "soft": "#fffdf7"},
    1: {"name": "Pinkish Red", "primary": "#9b314d", "deep": "#4b1021", "accent": "#e3a1b0", "soft": "#fff4f6"},
    2: {"name": "Green", "primary": "#2f6f4e", "deep": "#103d2a", "accent": "#9cc9a9", "soft": "#f2faf4"},
    3: {"name": "Yellow", "primary": "#c28a16", "deep": "#5c3e05", "accent": "#f0cf6b", "soft": "#fff9e8"},
    4: {"name": "Silver", "primary": "#7c858f", "deep": "#303841", "accent": "#d8dde2", "soft": "#f7f9fb"},
    5: {"name": "Bright Blue", "primary": "#1769aa", "deep": "#082c4d", "accent": "#82c9ff", "soft": "#f0f8ff"},
    6: {"name": "Maroon / Orange", "primary": "#7d1822", "deep": "#35060b", "accent": "#e08a32", "soft": "#fff4e9"},
}

def india_now():
    # Always calculate the current time in India, independent of the server/GMT timezone.
    return datetime.now(timezone.utc).astimezone(ZoneInfo("Asia/Kolkata"))

TODAY_IST = india_now()
TODAY_THEME = WEEKDAY_THEMES[TODAY_IST.weekday()]
# Two daily phases in IST: 05:30 AM–05:30 PM light, then dark.
LIGHT_START = TODAY_IST.replace(hour=5, minute=30, second=0, microsecond=0)
DARK_START = TODAY_IST.replace(hour=17, minute=30, second=0, microsecond=0)
THEME_PHASE = 'Light' if LIGHT_START <= TODAY_IST < DARK_START else 'Dark'
PHASE_BG = TODAY_THEME['soft'] if THEME_PHASE == 'Light' else '#12090b'
PHASE_SURFACE = '#fffdf8' if THEME_PHASE == 'Light' else '#241216'
PHASE_TEXT = TODAY_THEME['deep'] if THEME_PHASE == 'Light' else '#fff1d0'
PHASE_MUTED = '#6f625b' if THEME_PHASE == 'Light' else '#d7c5b6'
