if not st.session_state.logged_in:
    login_screen()
else:
    pages = {
        "home": home,
        "seva": seva_page,
        "darshan": darshan,
        "aarti": aarti,
        "japa": japa,
        "kalash": kalash,
        "navratri": navratri,
        "account": account,
        "history": history,
    }

    pages.get(st.session_state.page, home)()
    bottom_nav()
